WITH web_events_by_session AS (SELECT session_id, COUNT(duration_sec) AS duration_sec_count, COUNT(DISTINCT duration_sec) AS unique_pages FROM web_events WHERE page = '/home' GROUP BY session_id) SELECT s.id, s.customer_id, webs.duration_sec_count, webs.unique_pages FROM sessions s JOIN web_events_by_session webs ON s.id = webs.session_id WHERE webs.unique_pages >= 7 ORDER BY webs.duration_sec_count DESC, unique_pages DESC
